import numpy as np
import time
from scipy.optimize import minimize


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    Lp = np.concatenate(([0.0], L, [0.0]))
    quad = np.sum(Lp[:-1] ** 2 + Lp[:-1] * Lp[1:] + Lp[1:] ** 2) / 3.0
    inf = L.max()
    if inf <= 0:
        return 0.0
    return quad / (s * s * inf)


