import numpy as np
import time


def _R(h):
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    a = L[:-1]
    b = L[1:]
    q = (L @ L + a @ b) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return q / (s * s * inf)


def _R_and_grad(h):
    n = len(h)
    L = np.convolve(h, h)
    s = h.sum()
    if s <= 0:
        return -1.0, np.zeros(n)
    jmax = int(np.argmax(L))
    M = L[jmax]
    if M <= 0:
        return -1.0, np.zeros(n)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]
    b = Lf[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    r = q / (s * s * M)
    left = Lf[:-2]
    right = Lf[2:]
    dq_dL = (left + 2 * L) / 3.0 + (2 * L + right) / 3.0
    corr = np.correlate(dq_dL, h, mode='valid')
    dq_dh = 2.0 * corr
    dM_dh = np.zeros(n)
    lo = max(0, jmax - (n - 1))
    hi = min(n - 1, jmax)
    idx = np.arange(lo, hi + 1)
    dM_dh[idx] = 2.0 * h[jmax - idx]
    denom = s * s * M
    dR = dq_dh / denom - q * (2.0 / s + dM_dh / M) / denom
    return r, dR


def _climb(h, deadline, max_evals, lr=0.05, patience=40):
    h = np.maximum(h.astype(float), 0.0)
    r = _R(h)
    if r <= 0:
        return h, r
    n = len(h)
    evals = 0
    no_imp = 0
    while evals < max_evals and time.process_time() < deadline:
        _, g = _R_and_grad(h)
        gn = np.linalg.norm(g)
        if gn < 1e-14:
            break
        hscale = h.mean() + 1e-12
        step = lr * hscale * g / gn * np.sqrt(n)
        improved = False
        for sc in (1.0, 0.5, 0.25, 0.1, 0.03, 0.01):
            hn = np.maximum(h + step * sc, 0.0)
            if hn.sum() <= 0:
                continue
            nr = _R(hn)
            evals += 1
            if nr > r + 1e-14:
                h = hn
                r = nr
                improved = True
                break
            if time.process_time() >= deadline:
                break
        if not improved:
            lr *= 0.6
            no_imp += 1
            if lr < 1e-9 or no_imp > patience:
                break
        else:
            no_imp = 0
    return h, r


def _coord(h, r, deadline, max_evals, step, rng):
    h = h.copy()
    n = len(h)
    evals = 0
    order = rng.permutation(n)
    idx = 0
    improved_any = False
    while evals < max_evals and time.process_time() < deadline:
        i = int(order[idx % n])
        idx += 1
        if idx % n == 0:
            order = rng.permutation(n)
        old = h[i]
        delta = step * (h.mean() + 1e-9) * rng.standard_normal()
        new_val = max(0.0, old + delta)
        if new_val == old:
            continue
        h[i] = new_val
        if h.sum() <= 0:
            h[i] = old
            evals += 1
            continue
        nr = _R(h)
        evals += 1
        if nr > r + 1e-14:
            r = nr
            improved_any = True
        else:
            h[i] = old
    return h, r, improved_any


