    r = _R(h)
    if r <= 0:
        return h, r
    n = len(h)
    evals = 0
    no_imp = 0
    while evals < max_evals and time.process_time() < deadline:
        _, g = _R_and_grad(h)
        gn = np.linalg.norm(g)
        if gn < 1e-14:
