    for dn in (-2, -1, 1, 2, 3):
        if time.process_time() >= deadline:
            break
        new_n = len(best) + dn
        if 3 <= new_n <= 60:
            h, r = _refine_support(best, best_r, deadline, rng, new_n)
            if r > best_r:
                best, best_r = h, r

