                  max(3, len(best) // 2), max(3, len(best) // 3)):
        if time.process_time() >= deadline:
            break
        if 3 <= new_n <= 100:
            h, r = _refine_support(best, best_r, deadline, rng, new_n)
            if r > best_r:
                best, best_r = h, r

    # NEW Phase 5: upsampling to a fine grid and polishing.
