        pert = best * np.exp(scale * rng.standard_normal(len(best)))
        pert = np.maximum(pert, 0.0)
        if pert.sum() <= 0:
            continue
        h, r = _lbfgsb(pert, deadline, maxiter=150)
        if r > best_r:
            best, best_r = h.copy(), r
            h, r = _polish(best, deadline, rng, rounds=2)
            if r > best_r:
                best, best_r = h.copy(), r

    # Phase 4: rescale to other sizes.
    for factor in (2, 3, 0.5):
        if time.process_time() >= deadline:
            break
        new_n = int(round(len(best) * factor))
        if 3 <= new_n <= 1000:
