        if not imp and step < 0.03:
            break
    if time.process_time() < deadline:
        h, r = _climb(best_h.copy(), deadline, budget_evals // 2, lr=0.03)
        if r > best_r:
            best_h, best_r = h.copy(), r
    return best_h, best_r


def _upsample(h, new_n):
    n = len(h)
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, new_n)
    return np.maximum(np.interp(x_new, x_old, h), 0.0)


def _polish_fine(h, deadline, rng, evals=4000):
    h, r = _climb(h, deadline, evals, lr=0.05)
    if time.process_time() >= deadline:
        return h, r
    for step in (0.1, 0.05, 0.02, 0.01):
        if time.process_time() >= deadline:
            break
        h, r, imp = _coord(h, r, deadline, max(300, len(h) * 4), step, rng)
        if not imp and step < 0.03:
            break
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0
    rng = np.random.default_rng(20240607)

