            np.sin(np.pi * (x + 1) / 2.0) ** 2 + 1e-3,
            np.exp(-0.5 * (x / 0.4) ** 2),
        ]

    for n in Ns:
        if time.process_time() >= deadline:
            break
        for c in shapes(n):
            if time.process_time() >= deadline:
                break
            if c.sum() <= 0:
                continue
            h, r = _climb(c.astype(float).copy(), deadline, 2000, lr=0.2)
            if r > best_r - 0.02:
                h, r = _run(h, deadline, rng, 2500)
            if r > best_r:
                best, best_r = h.copy(), r

    # Phase 1b: resample the current best to nearby sizes and polish.
    for dn in (-3, -2, -1, 1, 2, 3, 4):
        if time.process_time() >= deadline:
            break
        new_n = len(best) + dn
        if 3 <= new_n <= 80:
            hn = _upsample(best, new_n)
            h, r = _run(hn, deadline, rng, 3000)
            if r > best_r:
                best, best_r = h, r

    # Phase 1c: NEW — upsampling to fine grids to carve the plateau/edges.
    for fine_n in (100, 200, 400, 800, 1600):
        if time.process_time() >= deadline:
            break
        hn = _upsample(best, fine_n)
        h, r = _polish_fine(hn, deadline, rng, evals=3000)
        if r > best_r:
            best, best_r = h, r

    # Phase 2: alternating polish on best, decreasing step.
    cur = best.copy()
    cur_r = best_r
