        if not imp:
            step *= 0.5
            if step < 1e-4:
                break

    best = np.maximum(np.asarray(best, dtype=float), 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    a = L[:-1]
    b = L[1:]
    q = (L @ L + a @ b) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return q / (s * s * inf)


def _R_and_grad(h):
    n = len(h)
    L = np.convolve(h, h)
    s = h.sum()
    if s <= 0:
        return -1.0, np.zeros(n)
    jmax = int(np.argmax(L))
    M = L[jmax]
    if M <= 0:
        return -1.0, np.zeros(n)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]
    b = Lf[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    r = q / (s * s * M)
    left = Lf[:-2]
    right = Lf[2:]
    dq_dL = (left + 2 * L) / 3.0 + (2 * L + right) / 3.0
    corr = np.correlate(dq_dL, h, mode='valid')
    dq_dh = 2.0 * corr
    dM_dh = np.zeros(n)
    lo = max(0, jmax - (n - 1))
    hi = min(n - 1, jmax)
    idx = np.arange(lo, hi + 1)
    dM_dh[idx] = 2.0 * h[jmax - idx]
    denom = s * s * M
    dR = dq_dh / denom - q * (2.0 / s + dM_dh / M) / denom
    return r, dR


def _lbfgsb(h0, deadline, maxiter=800):
    h0 = np.maximum(np.asarray(h0, dtype=float), 0.0)
    if h0.sum() <= 0:
        return h0, -1.0
    m = h0.mean()
    x0 = h0 / m if m > 0 else h0
    best_x = x0.copy()
    best_r = _R(x0)

    def fg(x):
        r, g = _R_and_grad(x)
        return -r, -g

    try:
        res = minimize(fg, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0),
                       options={'maxiter': maxiter, 'ftol': 1e-16,
                                'gtol': 1e-14, 'maxcor': 30,
                                'maxls': 50})
        x = np.maximum(res.x, 0.0)
        r = _R(x)
        if r > best_r:
            best_x, best_r = x, r
    except Exception:
        pass
    return best_x, best_r


def _R_sym(y):
    """R for symmetric h built from half-vector y. odd n: h = [y[::-1][:-1], y]; even: [y[::-1], y]."""
    n2 = len(y)
    h = np.concatenate([y[::-1], y])
    return _R(h)


def _R_and_grad_sym(y, even):
    """Gradient of R wrt half-vector y for symmetric h."""
    n2 = len(y)
    if even:
        h = np.concatenate([y[::-1], y])
    else:
        h = np.concatenate([y[::-1][:-1], y])
    r, g = _R_and_grad(h)
    n = len(h)
    # h[i] = y[n2-1-i] for i in [0, n2-1] (even) or [0, n2-2] (odd)
    # h[i+n2] = y[i] for i in [0, n2-1] (even) or h[i+n2-1]=y[i] (odd)
    gy = np.zeros(n2)
    if even:
        # h[0..n2-1] = y[n2-1..0], h[n2..2n2-1] = y[0..n2-1]
        for i in range(n2):
            gy[i] += g[n2 + i]  # h[n2+i] = y[i]
            gy[n2 - 1 - i] += g[i]  # h[i] = y[n2-1-i]
    else:
        # n = 2*n2 - 1. h[0..n2-2] = y[n2-1..1], h[n2-1]=y[0], h[n2..n-1]=y[1..n2-1]
        for i in range(n2):
            gy[i] += g[n2 - 1 + i]  # h[n2-1+i] = y[i]
            if i >= 1:
                gy[i] += g[n2 - 1 - i]  # h[n2-1-i] = y[i]
    return r, gy


def _lbfgsb_sym(y0, deadline, even, maxiter=800):
    y0 = np.maximum(np.asarray(y0, dtype=float), 0.0)
    if y0.sum() <= 0:
        return y0, -1.0
    m = y0.mean()
    x0 = y0 / m if m > 0 else y0
    best_x = x0.copy()
    best_r = _R_sym(x0)

    def fg(x):
        r, g = _R_and_grad_sym(x, even)
        return -r, -g

    try:
        res = minimize(fg, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0),
                       options={'maxiter': maxiter, 'ftol': 1e-16,
                                'gtol': 1e-14, 'maxcor': 30, 'maxls': 50})
        x = np.maximum(res.x, 0.0)
        r = _R_sym(x)
        if r > best_r:
            best_x, best_r = x, r
    except Exception:
        pass
    return best_x, best_r


def _sym_polish(h, deadline, rng, rounds=6):
    """Polish h by symmetrizing, optimizing in symmetric subspace, then full L-BFGS-B."""
    best_h = np.maximum(h.copy(), 0.0)
    best_r = _R(best_h)
    for _ in range(rounds):
        if time.process_time() >= deadline:
            break
        n = len(best_h)
        # symmetrize
        hs = 0.5 * (best_h + best_h[::-1])
        rs = _R(hs)
        if rs > best_r:
            best_h, best_r = hs, rs
        # symmetric optimization
        n2 = (n + 1) // 2
        even = (n % 2 == 0)
        y0 = hs[n2 - 1:] if not even else hs[n2:]
        y, r = _lbfgsb_sym(y0, deadline, even, maxiter=500)
        if even:
            hh = np.concatenate([y[::-1], y])
        else:
            hh = np.concatenate([y[::-1][:-1], y])
        if r > best_r:
            best_h, best_r = hh, r
        if time.process_time() >= deadline:
            break
        # full optimization
        hh, r = _lbfgsb(best_h, deadline, maxiter=600)
        if r > best_r:
            best_h, best_r = hh, r
    return best_h, best_r


def _coord(h, r, deadline, max_evals, step, rng):
    h = h.copy()
    n = len(h)
    evals = 0
    order = rng.permutation(n)
    idx = 0
    improved_any = False
    while evals < max_evals and time.process_time() < deadline:
        i = int(order[idx % n])
        idx += 1
        if idx % n == 0:
            order = rng.permutation(n)
        old = h[i]
        delta = step * (h.mean() + 1e-9) * rng.standard_normal()
        new_val = max(0.0, old + delta)
        if new_val == old:
            continue
        h[i] = new_val
        if h.sum() <= 0:
            h[i] = old
            evals += 1
            continue
        nr = _R(h)
        evals += 1
        if nr > r + 1e-15:
            r = nr
            improved_any = True
        else:
            h[i] = old
    return h, r, improved_any


def _resample(h, new_n):
    n = len(h)
    if new_n <= 0 or new_n == n:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, new_n)
    hn = np.interp(x_new, x_old, h)
    return np.maximum(hn, 0.0)


def _sym_perturb(h, scale, rng):
    """Perturb while preserving approximate symmetry."""
    hs = 0.5 * (h + h[::-1])
    pert = hs * np.exp(scale * rng.standard_normal(len(h)))
    pert = 0.5 * (pert + pert[::-1])
    return np.maximum(pert, 0.0)


