    if time.process_time() < deadline:
        h, r = _run(best, deadline, rng, 8000)
        if r > best_r:
            best, best_r = h, r

    # Extend: symmetric Gaussian family init at fine resolutions.
    for n in (16, 20, 24, 30, 40, 50):
        if time.process_time() >= deadline:
            break
        x = np.linspace(-1, 1, n)
        for sig in (0.3, 0.4, 0.5, 0.6, 0.8, 1.0):
            if time.process_time() >= deadline:
                break
            c = np.exp(-0.5 * (x / sig) ** 2) + 1e-3
            h, r = _climb(c, deadline, 2500, lr=0.2)
            if r > best_r - 0.03:
                h, r = _run(h, deadline, rng, 2000)
            if r > best_r:
