    q = (L @ L + a @ b) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return q / (s * s * inf)


def _R_and_grad(h):
    n = len(h)
    L = np.convolve(h, h)
    s = h.sum()
    if s <= 0:
        return -1.0, np.zeros(n)
    jmax = int(np.argmax(L))
    M = L[jmax]
    if M <= 0:
        return -1.0, np.zeros(n)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]
    b = Lf[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    r = q / (s * s * M)
    left = Lf[:-2]
    right = Lf[2:]
    dq_dL = (left + 2 * L) / 3.0 + (2 * L + right) / 3.0
    corr = np.correlate(dq_dL, h, mode='valid')
    dq_dh = 2.0 * corr
    dM_dh = np.zeros(n)
    lo = max(0, jmax - (n - 1))
    hi = min(n - 1, jmax)
    idx = np.arange(lo, hi + 1)
    dM_dh[idx] = 2.0 * h[jmax - idx]
    denom = s * s * M
    dR = dq_dh / denom - q * (2.0 / s + dM_dh / M) / denom
    return r, dR


def _lbfgsb(h0, deadline, maxiter=400):
    h0 = np.maximum(np.asarray(h0, dtype=float), 0.0)
    if h0.sum() <= 0:
        return h0, -1.0
    m = h0.mean()
    x0 = h0 / m if m > 0 else h0
    best_x = x0.copy()
    best_r = _R(x0)

    def fg(x):
        r, g = _R_and_grad(x)
        return -r, -g

    try:
        res = minimize(fg, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0),
                       options={'maxiter': maxiter, 'ftol': 1e-15,
                                'gtol': 1e-12, 'maxcor': 20})
        x = np.maximum(res.x, 0.0)
        r = _R(x)
        if r > best_r:
            best_x, best_r = x, r
    except Exception:
        pass
    return best_x, best_r


def _coord(h, r, deadline, max_evals, step, rng):
    h = h.copy()
    n = len(h)
    evals = 0
    order = rng.permutation(n)
    idx = 0
    improved_any = False
    while evals < max_evals and time.process_time() < deadline:
        i = int(order[idx % n])
        idx += 1
        if idx % n == 0:
            order = rng.permutation(n)
        old = h[i]
        delta = step * (h.mean() + 1e-9) * rng.standard_normal()
        new_val = max(0.0, old + delta)
        if new_val == old:
            continue
        h[i] = new_val
        if h.sum() <= 0:
            h[i] = old
            evals += 1
            continue
        nr = _R(h)
        evals += 1
        if nr > r + 1e-14:
            r = nr
            improved_any = True
        else:
            h[i] = old
    return h, r, improved_any


def _resample(h, new_n):
    n = len(h)
    if new_n <= 0 or new_n == n:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, new_n)
    hn = np.interp(x_new, x_old, h)
    return np.maximum(hn, 0.0)


def _polish(h, deadline, rng, rounds=3):
    best_h = h.copy()
    best_r = _R(best_h)
    for _ in range(rounds):
        if time.process_time() >= deadline:
            break
        h, r = _lbfgsb(best_h, deadline, maxiter=300)
        if r > best_r:
            best_h, best_r = h, r
        if time.process_time() >= deadline:
            break
        for step in (0.1, 0.05, 0.02, 0.01):
            h, r, imp = _coord(best_h, best_r, deadline,
                               max(200, len(best_h) * 8), step, rng)
            if r > best_r:
                best_h, best_r = h, r
            if not imp:
                break
            if time.process_time() >= deadline:
                break
    return best_h, best_r


def _perturb_and_polish(best, best_r, deadline, rng, n_tries):
    n = len(best)
    for _ in range(n_tries):
        if time.process_time() >= deadline:
            break
        scale = 0.03 + 0.25 * rng.random()
        pert = best * np.exp(scale * rng.standard_normal(n))
        pert = np.maximum(pert, 0.0)
        if pert.sum() <= 0:
            continue
        h, r = _lbfgsb(pert, deadline, maxiter=200)
        if r > best_r:
            h, r = _polish(h, deadline, rng, rounds=2)
            if r > best_r:
                best, best_r = h.copy(), r
    return best, best_r


def _smooth_conv(h, kernel):
    """Convolve h with small smoothing kernel (no shape change at edges)."""
    out = np.convolve(h, kernel, mode='same')
    return np.maximum(out, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(20240607)

    if start is not None:
        best = np.maximum(np.asarray(start, dtype=float).ravel().copy(), 0.0)
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(12)
    else:
        best = np.ones(12)
    best_r = _R(best)

    # Phase 0: hard polish of start.
    if time.process_time() < deadline:
        h, r = _polish(best, deadline, rng, rounds=8)
        if r > best_r:
            best, best_r = h, r

    # Phase 1: size scan around best with polish.
    base_n = len(best)
    for dn in (-2, -1, 1, 2, 3, -3):
        if time.process_time() >= deadline:
            break
        new_n = base_n + dn
        if 3 <= new_n <= 500:
            hn = _resample(best, new_n)
            h, r = _polish(hn, deadline, rng, rounds=4)
            if r > best_r:
                best, best_r = h.copy(), r

    # Phase 2: perturbations+polish at current size (exploit).
    best, best_r = _perturb_and_polish(best, best_r, deadline, rng, 400)

    # Phase 3: targeted support-trimming (zeros at ends).
    if time.process_time() < deadline:
        for k in (1, 2, 3, 4):
            if len(best) > 2 * k + 2:
                cand = best.copy()
                cand[:k] = 0.0
                cand[-k:] = 0.0
                h, r = _polish(cand, deadline, rng, rounds=4)
                if r > best_r:
                    best, best_r = h.copy(), r

    # Phase 3b: NEW — smooth-and-polish.  Smoothing escapes small local basins
    # which the raw perturbations can't reach (they preserve the shape too well).
    if time.process_time() < deadline:
        for ker in ([0.25, 0.5, 0.25], [0.2, 0.6, 0.2], [0.4, 0.2, 0.4]):
            if time.process_time() >= deadline:
                break
            cand = _smooth_conv(best, np.array(ker))
            if cand.sum() <= 0:
                continue
            h, r = _polish(cand, deadline, rng, rounds=4)
            if r > best_r:
                best, best_r = h.copy(), r

    # Phase 4: multistart from random shapes at small N (explore).
    if time.process_time() < deadline:
        Ns = [8, 10, 12, 14, 16, 20]
        for n in Ns:
            if time.process_time() >= deadline:
                break
            for _ in range(8):
                if time.process_time() >= deadline:
                    break
                c = rng.random(n) + 0.05
                h, r = _lbfgsb(c, deadline, maxiter=300)
                if r > best_r - 0.005:
                    h, r = _polish(h, deadline, rng, rounds=2)
                    if r > best_r:
                        best, best_r = h.copy(), r

    # Phase 5: resample best to nearby sizes and polish again.
    for dn in (-4, -2, -1, 1, 2, 4, 6):
        if time.process_time() >= deadline:
            break
        new_n = len(best) + dn
        if 3 <= new_n <= 300:
            hn = _resample(best, new_n)
            h, r = _polish(hn, deadline, rng, rounds=3)
            if r > best_r:
                best, best_r = h.copy(), r

    # Phase 6: more perturbations.
    best, best_r = _perturb_and_polish(best, best_r, deadline, rng, 400)

    # Final polish.
    if time.process_time() < deadline:
        h, r = _polish(best, deadline, rng, rounds=6)
        if r > best_r:
            best, best_r = h, r

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(12)
    return best

