def _nelder_mead(h0, deadline, maxiter=2000):
    x0 = np.maximum(np.asarray(h0, dtype=float), 0.0)
    if x0.sum() <= 0:
        return x0, -1.0
    x0 = x0 / x0.mean()

    def f(x):
        if time.process_time() >= deadline:
            raise RuntimeError("stop")
        return -_R(np.maximum(x, 0.0))

    try:
        res = minimize(f, x0, method='Nelder-Mead',
                       options={'maxiter': maxiter, 'xatol': 1e-12,
                                'fatol': 1e-16, 'adaptive': True})
        x = np.maximum(res.x, 0.0)
        return x, _R(x)
    except Exception:
        return x0, _R(x0)


def _resample(h, new_n):
    n = len(h)
    if new_n <= 0 or new_n == n:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, new_n)
    return np.maximum(np.interp(x_new, x_old, h), 0.0)


def _polish(h, deadline, rng, rounds=3):
    best_h = np.maximum(np.asarray(h, dtype=float).copy(), 0.0)
    best_r = _R(best_h)
    for _ in range(rounds):
        if time.process_time() >= deadline:
            break
        h2, r = _lbfgsb(best_h, deadline, maxiter=500)
        if r > best_r:
            best_h, best_r = h2, r
    if time.process_time() < deadline:
        h2, r = _nelder_mead(best_h, deadline, maxiter=1200)
        if r > best_r:
            best_h, best_r = h2, r
    return best_h, best_r


def _perturb(h, rng, scale):
    pert = h * np.exp(scale * rng.standard_normal(len(h)))
    return np.maximum(pert, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0
    rng = np.random.default_rng(987654321)

    if start is not None:
        best = np.maximum(np.asarray(start, dtype=float).ravel().copy(), 0.0)
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(12)
    else:
        best = np.ones(12)
    best_r = _R(best)

    def upd(h, r):
        nonlocal best, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return
        if r > best_r + 1e-15:
            best = h.copy()
            best_r = r

    # Phase 0: hard polish of start.
    if time.process_time() < deadline:
        h, r = _lbfgsb(best, deadline, maxiter=6000)
        upd(h, r)
        h, r = _polish(best, deadline, rng, rounds=4)
        upd(h, r)

    # Phase 1: sweep sizes near current best N (fine grid).
    n0 = len(best)
    sizes = []
    for dn in list(range(-6, 7)):
        nn = n0 + dn
        if 3 <= nn <= 120 and nn not in sizes:
            sizes.append(nn)
    for n in sizes:
        if time.process_time() >= deadline:
            break
        hn = _resample(best, n)
        h, r = _lbfgsb(hn, deadline, maxiter=1000)
        upd(h, r)
        if r > best_r - 0.005 and time.process_time() < deadline:
            h, r = _polish(h, deadline, rng, rounds=2)
            upd(h, r)

    # Phase 2: aggressive perturbation search around best.
    n_pert = 0
    while time.process_time() < deadline - 0.4 and n_pert < 600:
        n_pert += 1
        scale = 0.005 + 0.25 * rng.random()
        pert = _perturb(best, rng, scale)
        if pert.sum() <= 0:
            continue
        h, r = _lbfgsb(pert, deadline, maxiter=600)
        upd(h, r)
        if r > best_r - 0.002 and time.process_time() < deadline:
            h, r = _polish(h, deadline, rng, rounds=2)
            upd(h, r)

    # Phase 3: split/merge micro-exploration on best size.
    if time.process_time() < deadline - 0.5:
        n = len(best)
        for i in range(min(n, 80)):
            if time.process_time() >= deadline - 0.3:
                break
            a = best[i]
            b = best[i + 1] if i + 1 < n else best[i]
            mid = 0.5 * (a + b)
            cand = np.concatenate((best[:i + 1], [mid], best[i + 1:]))
            h, r = _lbfgsb(cand, deadline, maxiter=400)
            if r > best_r:
                upd(h, r)
                h2, r2 = _polish(h, deadline, rng, rounds=2)
                upd(h2, r2)

    # Final polish.
    if time.process_time() < deadline:
        h, r = _polish(best, deadline, rng, rounds=6)
        upd(h, r)
        if time.process_time() < deadline:
            h, r = _lbfgsb(best, deadline, maxiter=10000)
            upd(h, r)

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(12)
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    s = h.sum()
    if s <= 0.0:
        return -1.0
    L = np.convolve(h, h)
    a = L[:-1]
    b = L[1:]
    q = (L @ L + a @ b) / 3.0
    M = L.max()
    if M <= 0:
        return -1.0
    return q / (s * s * M)


def _R_and_grad(h, smooth=0.0):
    n = len(h)
    L = np.convolve(h, h)
    s = h.sum()
    if s <= 0:
        return -1.0, np.zeros(n)
    M = L.max()
    if M <= 0:
        return -1.0, np.zeros(n)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]
    b = Lf[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    left = Lf[:-2]
    right = Lf[2:]
    dq_dL = (left + 2 * L) / 3.0 + (2 * L + right) / 3.0
    dq_dh = 2.0 * np.correlate(dq_dL, h, mode='valid')

    if smooth > 0.0:
        e = np.exp((L - M) / smooth)
        Z = e.sum()
        w = e / Z
        dM_dh = np.zeros(n)
        for jmax in range(n):
            wj = w[jmax]
            if wj < 1e-12:
                continue
            lo = max(0, jmax - (n - 1))
            hi = min(n - 1, jmax)
            idx = np.arange(lo, hi + 1)
            dM_dh[idx] += wj * 2.0 * h[jmax - idx]
    else:
        thr = M - 1e-7 * M
        tied = np.where(L >= thr)[0]
        if len(tied) == 0:
            tied = np.array([int(np.argmax(L))])
        dM_dh = np.zeros(n)
        ww = 1.0 / len(tied)
        for jmax in tied:
            lo = max(0, jmax - (n - 1))
            hi = min(n - 1, jmax)
            idx = np.arange(lo, hi + 1)
            dM_dh[idx] += ww * 2.0 * h[jmax - idx]

    denom = s * s * M
    dR = dq_dh / denom - q * (2.0 / s + dM_dh / M) / denom
    return q / denom, dR


def _lbfgsb(h0, deadline, maxiter=400, smooth=0.0):
    h0 = np.maximum(np.asarray(h0, dtype=float), 0.0)
    if h0.sum() <= 0:
        return h0, -1.0
    m = h0.mean()
    x0 = h0 / m if m > 0 else h0
    best_x = x0.copy()
    best_r = _R(x0)
    stop = [False]

    def fg(x):
        if stop[0] or time.process_time() >= deadline:
            stop[0] = True
            raise RuntimeError("stop")
        r, g = _R_and_grad(x, smooth=smooth)
        return -r, -g

    try:
        res = minimize(fg, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0),
                       options={'maxiter': maxiter, 'ftol': 1e-17,
                                'gtol': 1e-14, 'maxcor': 40})
        x = np.maximum(res.x, 0.0)
        r = _R(x)
        if r > best_r:
            best_x, best_r = x, r
    except Exception:
        pass
    return best_x, best_r


def _resample(h, new_n):
    n = len(h)
    if new_n <= 0 or new_n == n:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n)
