    return np.maximum(np.interp(x_new, x_old, h), 0.0)


def _coord_polish(h0, deadline, passes=6):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0).copy()
    r = _R(h)
    n = len(h)
    if n == 0 or h.sum() <= 0:
