                return h, r
            base = h[i]
            best_v = base
            best_r = r
            for fac in (0.0, 0.5, 0.7, 0.85, 0.95, 1.05, 1.15, 1.3, 1.5, 2.0, 3.0):
                h[i] = base * fac
                if h.sum() <= 0:
                    continue
                rr = _R(h)
                if rr > best_r:
                    best_r = rr
                    best_v = base * fac
            for dv in (-0.1, -0.03, -0.01, 0.01, 0.03, 0.1):
                h[i] = max(0.0, base + dv * (h.mean() + 1e-9))
                if h.sum() <= 0:
                    continue
                rr = _R(h)
                if rr > best_r:
                    best_r = rr
                    best_v = h[i]
            h[i] = best_v
            if best_r > r + 1e-16:
                r = best_r
                improved = True
        if not improved:
            break
    return h, r


def _polish(h, deadline, rounds=3):
    best_h = np.maximum(np.asarray(h, dtype=float).copy(), 0.0)
    best_r = _R(best_h)
    if best_h.sum() <= 0:
