        h2, r = _coord_polish(best_h, deadline, passes=3)
        if r > best_r:
            best_h, best_r = h2, r
    return best_h, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0
    rng = np.random.default_rng(20250101)

