            if r > best_r:
                best, best_r = c.copy(), r

    # Multi-scale resampling to find good lengths
    base = best.copy()
    for N in range(max(3, base.size - 8), min(120, base.size + 12)):
        if time.process_time() >= deadline:
            break
        t = _resample(base, N)
        r = _R(t)
        if r > best_r:
            best, best_r = t, r

    # Core optimization: alternate L-BFGS-B and coordinate polish
    best, best_r = _polish(best, deadline, rounds=6)

    # Random restarts around best with small perturbations
    while time.process_time() < deadline:
        trial = best.copy()
        k = max(1, int(trial.size * rng.uniform(0.03, 0.2)))
        idx = rng.integers(0, trial.size, size=k)
        trial[idx] *= np.exp(0.25 * rng.standard_normal(k))
        trial = np.maximum(trial, 0.0)
        if trial.sum() <= 0:
