                       options={'maxiter': maxiter, 'ftol': 1e-17,
                                'gtol': 1e-14, 'maxcor': 30})
        x = np.maximum(res.x, 0.0)
        r = _R(x)
        if r > best_r:
            best_x, best_r = x, r
    except Exception:
        pass
    return best_x, best_r


def _coord(h, r, deadline, max_evals, step, rng):
    h = h.copy()
    n = len(h)
    evals = 0
    order = rng.permutation(n)
    idx = 0
    improved_any = False
    while evals < max_evals and time.process_time() < deadline:
        i = int(order[idx % n])
        idx += 1
        if idx % n == 0:
            order = rng.permutation(n)
        old = h[i]
        delta = step * (h.mean() + 1e-9) * rng.standard_normal()
        new_val = max(0.0, old + delta)
        if new_val == old:
            continue
        h[i] = new_val
        if h.sum() <= 0:
            h[i] = old
            evals += 1
            continue
        nr = _R(h)
        evals += 1
        if nr > r + 1e-15:
            r = nr
            improved_any = True
        else:
            h[i] = old
    return h, r, improved_any


def _resample(h, new_n):
    n = len(h)
    if new_n <= 0 or new_n == n:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, new_n)
    hn = np.interp(x_new, x_old, h)
    return np.maximum(hn, 0.0)


def _polish(h, deadline, rng, rounds=3):
    best_h = np.maximum(np.asarray(h, dtype=float).copy(), 0.0)
    best_r = _R(best_h)
    for _ in range(rounds):
        if time.process_time() >= deadline:
            break
        h2, r = _lbfgsb(best_h, deadline, maxiter=500)
        if r > best_r:
            best_h, best_r = h2, r
        if time.process_time() >= deadline:
            break
        for step in (0.08, 0.03, 0.01, 0.003, 0.001, 0.0003):
            h2, r, imp = _coord(best_h, best_r, deadline,
                                max(200, len(best_h) * 6), step, rng)
            if r > best_r:
                best_h, best_r = h2, r
            if not imp:
                break
            if time.process_time() >= deadline:
                break
    return best_h, best_r


def _pad_zeros(h, k):
    """Embed h inside a longer array with k zeros on each side."""
    return np.concatenate((np.zeros(k), h, np.zeros(k)))


def _sym_polish(h, deadline, rng, rounds=4):
    """Optimise over (first half) then mirror; exploits near-symmetry of optimum."""
    best_h = np.maximum(np.asarray(h, dtype=float).copy(), 0.0)
    best_r = _R(best_h)
    n = len(best_h)
    sym = 0.5 * (best_h + best_h[::-1])
    if _R(sym) > best_r:
        best_h = sym
        best_r = _R(sym)
    for _ in range(rounds):
        if time.process_time() >= deadline:
            break
        # Optimise the symmetric parametrisation: free = first half
        half = (n + 1) // 2

        def expand(x):
            x = np.maximum(x, 0.0)
            if n % 2 == 0:
                return np.concatenate((x, x[::-1]))
            return np.concatenate((x, x[-2::-1]))

        x0 = best_h[:half].copy()

        def fg(x):
            if time.process_time() >= deadline:
                raise RuntimeError("stop")
            r, g = _R_and_grad(expand(x))
            gx = g[:half].copy()
            if n % 2 == 0:
                gx = gx + g[::-1][:half]
            else:
                gx = gx + g[::-1][:half]
            return -r, -gx

        try:
            res = minimize(fg, x0, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * half,
                           options={'maxiter': 600, 'ftol': 1e-17,
                                    'gtol': 1e-14, 'maxcor': 30})
            cand = expand(res.x)
            r = _R(cand)
            if r > best_r:
                best_h, best_r = cand, r
        except Exception:
            pass
        if time.process_time() >= deadline:
            break
        for step in (0.02, 0.006, 0.002, 0.0006):
            h2, r, imp = _coord(best_h, best_r, deadline,
                                max(200, n * 4), step, rng)
            if r > best_r:
                best_h, best_r = h2, r
            if not imp:
                break
    return best_h, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.2
    rng = np.random.default_rng(13579246)

    if start is not None:
        best = np.maximum(np.asarray(start, dtype=float).ravel().copy(), 0.0)
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(12)
    else:
        best = np.ones(12)
    best_r = _R(best)

    def upd(h, r):
        nonlocal best, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return
        if r > best_r + 1e-15:
            best = h.copy()
            best_r = r

    # Phase 0: hard polish of start.
    if time.process_time() < deadline:
        h, r = _lbfgsb(best, deadline, maxiter=4000)
        upd(h, r)
        h, r = _polish(best, deadline, rng, rounds=6)
        upd(h, r)

    # Phase 0b: symmetric parametrisation polish — the optimum is nearly
    # palindromic, so this halves the effective dimension and finds finer
    # improvements in the flat plateau region.
    if time.process_time() < deadline:
        h, r = _sym_polish(best, deadline, rng, rounds=5)
        upd(h, r)

    # Phase 1: zero-padding trick.
    n0 = len(best)
    for k in (1, 2, 3, 4, 6, 8):
        if time.process_time() >= deadline:
            break
        cand = _pad_zeros(best, k)
        h, r = _lbfgsb(cand, deadline, maxiter=800)
        upd(h, r)
        if r > best_r - 0.005:
            h, r = _polish(h, deadline, rng, rounds=3)
            upd(h, r)

    # Phase 2: resample best to nearby sizes and polish.
    base_n = len(best)
    for dn in (-4, -3, -2, -1, 1, 2, 3, 4, 6, 8, 10):
        if time.process_time() >= deadline:
            break
        new_n = base_n + dn
        if 3 <= new_n <= 500:
            hn = _resample(best, new_n)
            h, r = _polish(hn, deadline, rng, rounds=4)
            upd(h, r)

    # Phase 3: random multiplicative perturbations with polish.
    n_pert = 0
    while time.process_time() < deadline - 0.3 and n_pert < 400:
        n_pert += 1
        scale = 0.01 + 0.25 * rng.random()
        pert = best * np.exp(scale * rng.standard_normal(len(best)))
        pert = np.maximum(pert, 0.0)
        if pert.sum() <= 0:
            continue
        h, r = _lbfgsb(pert, deadline, maxiter=500)
        upd(h, r)
        if r > best_r - 0.002 and time.process_time() < deadline:
            h, r = _polish(h, deadline, rng, rounds=3)
            upd(h, r)

    # Phase 4: force zeros at ends (narrow support).
    for k in (1, 2, 3):
        if time.process_time() >= deadline:
            break
        if len(best) > 2 * k + 2:
            cand = best.copy()
            cand[:k] = 0.0
            cand[-k:] = 0.0
            h, r = _polish(cand, deadline, rng, rounds=3)
            upd(h, r)

    # Phase 5: final symmetric polish on the current best — squeezes the
    # remaining tiny gains out of the plateau.
    if time.process_time() < deadline:
        h, r = _sym_polish(best, deadline, rng, rounds=6)
        upd(h, r)

    # Final polish.
    if time.process_time() < deadline:
        h, r = _polish(best, deadline, rng, rounds=8)
        upd(h, r)

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(12)
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    s = h.sum()
    if s <= 0.0:
        return -1.0
    L = np.convolve(h, h)
    q = (L @ L + L[:-1] @ L[1:]) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return q / (s * s * inf)


def _R_and_grad(h, tie_tol=1e-3):
    n = len(h)
    L = np.convolve(h, h)
    s = h.sum()
    if s <= 0:
        return -1.0, np.zeros(n)
    M = L.max()
    if M <= 0:
        return -1.0, np.zeros(n)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]
    b = Lf[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    r = q / (s * s * M)
    left = Lf[:-2]
    right = Lf[2:]
    dq_dL = (left + 2 * L) / 3.0 + (2 * L + right) / 3.0
    dq_dh = 2.0 * np.correlate(dq_dL, h, mode='valid')
    thr = M - tie_tol * M
    dM_dh = np.zeros(n)
    tied = np.where(L >= thr)[0]
    w = 1.0 / len(tied)
    for jmax in tied:
        lo = max(0, jmax - (n - 1))
        hi = min(n - 1, jmax)
        idx = np.arange(lo, hi + 1)
        dM_dh[idx] += w * 2.0 * h[jmax - idx]
    denom = s * s * M
    dR = dq_dh / denom - q * (2.0 / s + dM_dh / M) / denom
    return r, dR


def _lbfgsb(h0, deadline, maxiter=400, tie_tol=1e-3):
    h0 = np.maximum(np.asarray(h0, dtype=float), 0.0)
    if h0.sum() <= 0:
        return h0, -1.0
    m = h0.mean()
    x0 = h0 / m if m > 0 else h0
    best_x = x0.copy()
    best_r = _R(x0)

    def fg(x):
        if time.process_time() >= deadline:
            raise RuntimeError("stop")
        r, g = _R_and_grad(x, tie_tol=tie_tol)
        return -r, -g

    try:
        res = minimize(fg, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0),
                       options={'maxiter': maxiter, 'ftol': 1e-18,
                                'gtol': 1e-15, 'maxcor': 40})
        x = np.maximum(res.x, 0.0)
        r = _R(x)
        if r > best_r:
            best_x, best_r = x, r
    except Exception:
        pass
    return best_x, best_r


