def _smooth_opt(h0, deadline, rng, fine_mult=4):
    """Optimise even-symmetric densely-parametrised profile, then coarsen."""
    n = len(h0)
    fine = fine_mult * n + 1
    xc = np.linspace(-1, 1, n)
    xf = np.linspace(-1, 1, fine)
    hf = np.interp(xf, xc, h0)
    hf = np.maximum(hf, 1e-6)
    half = (fine + 1) // 2
    hf[half:] = hf[:fine - half][::-1]

    def build_half(v):
        h = np.concatenate((v, v[:fine - half][::-1]))
        return np.maximum(h, 0.0)

    best_v = hf[:half].copy()
    best_r = _R(build_half(best_v))

    def fg(v):
        if time.process_time() >= deadline:
            raise RuntimeError("stop")
        h = build_half(v)
        r, g = _R_and_grad(h)
        gv = g[:half].copy()
        gv[:fine - half] += g[half:][::-1]
        return -r, -gv

    try:
        res = minimize(fg, best_v, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * half,
                       options={'maxiter': 3000, 'ftol': 1e-18,
                                'gtol': 1e-15, 'maxcor': 50})
        v = np.maximum(res.x, 0.0)
        h = build_half(v)
        edges = np.linspace(0, fine, n + 1)
        hc = np.zeros(n)
        for i in range(n):
            lo = int(edges[i]); hi = int(edges[i + 1])
            if hi <= lo:
                hi = lo + 1
            hc[i] = h[lo:hi].mean()
        hc = 0.5 * (hc + hc[::-1])
        rc = _R(hc)
        if rc > best_r:
            best_r = rc
            h = hc
        else:
            h = _resample(h, n)
        return h, best_r
    except Exception:
        return h0.copy(), _R(h0)


def _tie_aware_opt(h0, deadline, rng):
    best_h = np.maximum(np.asarray(h0, dtype=float).copy(), 0.0)
    best_r = _R(best_h)
    for tt in (1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5):
        if time.process_time() >= deadline:
            break
        h, r = _lbfgsb(best_h, deadline, maxiter=1500, tie_tol=tt)
        if r > best_r:
            best_h, best_r = h, r
    return best_h, best_r


def _smooth_gauss(h, sigma):
    """Convolve with a small Gaussian kernel (smoothing regulariser)."""
    if sigma <= 0:
        return h.copy()
    r = max(1, int(3 * sigma))
    x = np.arange(-r, r + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.2
    rng = np.random.default_rng(975312468)

    if start is not None:
        best = np.maximum(np.asarray(start, dtype=float).ravel().copy(), 0.0)
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(12)
    else:
        best = np.ones(12)
    best_r = _R(best)

    def upd(h, r):
        nonlocal best, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return
        if r > best_r + 1e-16:
            best = h.copy()
            best_r = r

    nz = np.nonzero(best)[0]
    if nz.size > 0:
        best = best[nz[0]:nz[-1] + 1].copy()
        best_r = _R(best)

    # Phase 0: hard polish of start (fine-tuned tie tolerance).
    if time.process_time() < deadline:
        h, r = _lbfgsb(best, deadline, maxiter=8000, tie_tol=1e-4)
        upd(h, r)
        h, r = _polish(best, deadline, rng, rounds=6)
        upd(h, r)

    # Phase 1: symmetric fine-grid optimisation at multiple fine multipliers.
    n0 = len(best)
    for fm in (2, 4, 6, 8):
        if time.process_time() >= deadline:
            break
        for n in (n0, n0 + 1, max(3, n0 - 1)):
            if time.process_time() >= deadline:
                break
            if not (3 <= n <= 500):
                continue
            hstart = _resample(best, n)
            h, r = _smooth_opt(hstart, deadline, rng, fine_mult=fm)
            upd(h, r)
            if r > best_r - 0.002 and time.process_time() < deadline:
                h, r = _polish(h, deadline, rng, rounds=4)
                upd(h, r)

    # Phase 2: tie-aware multi-start polish.
    if time.process_time() < deadline:
        h, r = _tie_aware_opt(best, deadline, rng)
        upd(h, r)

    # Phase 3: Gaussian smoothing + re-optimisation.
    # Regularised starts often land in better basins for the nonsmooth max term.
    n_cur = len(best)
    for sigma in (0.5, 1.0, 1.5, 2.0, 3.0):
        if time.process_time() >= deadline:
            break
        hs = _smooth_gauss(best, sigma)
        if hs.sum() <= 0:
            continue
        h, r = _lbfgsb(hs, deadline, maxiter=1500, tie_tol=1e-3)
        upd(h, r)
        if r > best_r - 0.003 and time.process_time() < deadline:
            h, r = _polish(h, deadline, rng, rounds=4)
            upd(h, r)
        # also try at slightly different grid sizes
        for dn in (1, -1):
            if time.process_time() >= deadline:
                break
            nn = n_cur + dn
            if 3 <= nn <= 500:
                hn = _resample(hs, nn)
                h, r = _polish(hn, deadline, rng, rounds=3)
                upd(h, r)

    # Phase 4: resample best to nearby sizes and polish.
    base_n = len(best)
    for dn in (1, -1, 2, -2, 3, -3, 4, 6, 8, 10, 12):
        if time.process_time() >= deadline:
            break
        new_n = base_n + dn
        if 3 <= new_n <= 500:
            hn = _resample(best, new_n)
            h, r = _polish(hn, deadline, rng, rounds=4)
            upd(h, r)

    # Phase 5: random multiplicative perturbations with polish.
    n_pert = 0
    while time.process_time() < deadline - 0.3 and n_pert < 200:
        n_pert += 1
        scale = 0.01 + 0.20 * rng.random()
        pert = best * np.exp(scale * rng.standard_normal(len(best)))
        pert = np.maximum(pert, 0.0)
        if pert.sum() <= 0:
            continue
        h, r = _lbfgsb(pert, deadline, maxiter=600)
        upd(h, r)
        if r > best_r - 0.002 and time.process_time() < deadline:
            h, r = _polish(h, deadline, rng, rounds=3)
            upd(h, r)

    # Phase 6: force zeros at ends (narrow support).
    for k in (1, 2, 3):
        if time.process_time() >= deadline:
            break
        if len(best) > 2 * k + 2:
            cand = best.copy()
            cand[:k] = 0.0
            cand[-k:] = 0.0
            h, r = _polish(cand, deadline, rng, rounds=3)
            upd(h, r)

    # Final tie-aware + polish to lock in a good tie configuration.
    if time.process_time() < deadline - 0.2:
        for tt in (3e-4, 1e-4, 3e-5):
            if time.process_time() >= deadline:
                break
            h, r = _lbfgsb(best, deadline, maxiter=2000, tie_tol=tt)
            upd(h, r)
    if time.process_time() < deadline:
        h, r = _polish(best, deadline, rng, rounds=8)
        upd(h, r)

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(12)
    return best

