def _coord(h, r, deadline, max_evals, step, rng):
    h = h.copy()
    n = len(h)
    evals = 0
    order = rng.permutation(n)
    idx = 0
    improved_any = False
    while evals < max_evals and time.process_time() < deadline:
        i = int(order[idx % n])
        idx += 1
        if idx % n == 0:
            order = rng.permutation(n)
        old = h[i]
        delta = step * (h.mean() + 1e-9) * rng.standard_normal()
        new_val = max(0.0, old + delta)
        if new_val == old:
            continue
        h[i] = new_val
        if h.sum() <= 0:
            h[i] = old
            evals += 1
            continue
        nr = _R(h)
        evals += 1
        if nr > r + 1e-16:
            r = nr
            improved_any = True
        else:
            h[i] = old
    return h, r, improved_any


def _resample(h, new_n):
    n = len(h)
    if new_n <= 0 or new_n == n:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, new_n)
    hn = np.interp(x_new, x_old, h)
    return np.maximum(hn, 0.0)


def _polish(h, deadline, rng, rounds=3):
    best_h = np.maximum(np.asarray(h, dtype=float).copy(), 0.0)
    best_r = _R(best_h)
    for _ in range(rounds):
        if time.process_time() >= deadline:
            break
        h2, r = _lbfgsb(best_h, deadline, maxiter=800)
        if r > best_r:
            best_h, best_r = h2, r
        if time.process_time() >= deadline:
            break
        for step in (0.05, 0.02, 0.008, 0.003, 0.001, 0.0003, 0.0001):
            h2, r, imp = _coord(best_h, best_r, deadline,
                                max(300, len(best_h) * 8), step, rng)
            if r > best_r:
                best_h, best_r = h2, r
            if not imp:
                break
            if time.process_time() >= deadline:
                break
    return best_h, best_r


def _smooth_opt(h0, deadline, rng, fine_mult=4):
    n = len(h0)
    fine = fine_mult * n + 1
    xc = np.linspace(-1, 1, n)
    xf = np.linspace(-1, 1, fine)
    hf = np.interp(xf, xc, h0)
    hf = np.maximum(hf, 1e-6)
    half = (fine + 1) // 2
    hf[half:] = hf[:fine - half][::-1]

    def build_half(v):
        h = np.concatenate((v, v[:fine - half][::-1]))
        return np.maximum(h, 0.0)

    best_v = hf[:half].copy()
    best_r = _R(build_half(best_v))

    def fg(v):
        if time.process_time() >= deadline:
            raise RuntimeError("stop")
        h = build_half(v)
        r, g = _R_and_grad(h)
        gv = g[:half].copy()
        gv[:fine - half] += g[half:][::-1]
        return -r, -gv

    try:
        res = minimize(fg, best_v, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * half,
                       options={'maxiter': 3000, 'ftol': 1e-18,
                                'gtol': 1e-15, 'maxcor': 50})
        v = np.maximum(res.x, 0.0)
        h = build_half(v)
        edges = np.linspace(0, fine, n + 1)
        hc = np.zeros(n)
        for i in range(n):
            lo = int(edges[i]); hi = int(edges[i + 1])
            if hi <= lo:
                hi = lo + 1
            hc[i] = h[lo:hi].mean()
        hc = 0.5 * (hc + hc[::-1])
        rc = _R(hc)
        if rc > best_r:
            best_r = rc
            h = hc
        else:
            h = _resample(h, n)
        return h, best_r
    except Exception:
        return h0.copy(), _R(h0)


def _tie_aware_opt(h0, deadline, rng):
    best_h = np.maximum(np.asarray(h0, dtype=float).copy(), 0.0)
    best_r = _R(best_h)
    for tt in (1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5):
        if time.process_time() >= deadline:
            break
        h, r = _lbfgsb(best_h, deadline, maxiter=1500, tie_tol=tt)
        if r > best_r:
            best_h, best_r = h, r
    return best_h, best_r


def _smooth_gauss(h, sigma):
    if sigma <= 0:
        return h.copy()
    r = max(1, int(3 * sigma))
    x = np.arange(-r, r + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def _slsqp_opt(h0, deadline, maxiter=400, tie_tol=1e-4):
    """SLSQP with explicit nonnegativity bounds; often better near active ties."""
    h0 = np.maximum(np.asarray(h0, dtype=float), 0.0)
    if h0.sum() <= 0:
        return h0, -1.0
    m = h0.mean()
    x0 = h0 / m if m > 0 else h0
    best_x = x0.copy()
    best_r = _R(x0)

    def fg(x):
        if time.process_time() >= deadline:
            raise RuntimeError("stop")
        r, g = _R_and_grad(x, tie_tol=tie_tol)
        return -r, -g

    try:
        res = minimize(fg, x0, jac=True, method='SLSQP',
                       bounds=[(0.0, None)] * len(x0),
                       options={'maxiter': maxiter, 'ftol': 1e-16})
        x = np.maximum(res.x, 0.0)
        r = _R(x)
        if r > best_r:
            best_x, best_r = x, r
    except Exception:
        pass
    return best_x, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.2
    rng = np.random.default_rng(975312468)

    if start is not None:
        best = np.maximum(np.asarray(start, dtype=float).ravel().copy(), 0.0)
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(12)
    else:
        best = np.ones(12)
    best_r = _R(best)

    def upd(h, r):
        nonlocal best, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return
        if r > best_r + 1e-16:
            best = h.copy()
            best_r = r

    nz = np.nonzero(best)[0]
    if nz.size > 0:
        best = best[nz[0]:nz[-1] + 1].copy()
        best_r = _R(best)

    # Phase 0: hard polish of start (fine-tuned tie tolerance).
    if time.process_time() < deadline:
        h, r = _lbfgsb(best, deadline, maxiter=8000, tie_tol=1e-4)
        upd(h, r)
        h, r = _polish(best, deadline, rng, rounds=6)
        upd(h, r)

    # Phase 0b: SLSQP passes (different active-set handling near ties/zeros).
    if time.process_time() < deadline:
        for tt in (1e-3, 1e-4, 1e-5):
            if time.process_time() >= deadline:
                break
            h, r = _slsqp_opt(best, deadline, maxiter=600, tie_tol=tt)
            upd(h, r)

    # Phase 1: symmetric fine-grid optimisation at multiple fine multipliers.
    n0 = len(best)
    for fm in (2, 4, 6, 8):
        if time.process_time() >= deadline:
            break
        for n in (n0, n0 + 1, max(3, n0 - 1)):
            if time.process_time() >= deadline:
                break
            if not (3 <= n <= 500):
                continue
            hstart = _resample(best, n)
            h, r = _smooth_opt(hstart, deadline, rng, fine_mult=fm)
            upd(h, r)
            if r > best_r - 0.002 and time.process_time() < deadline:
                h, r = _polish(h, deadline, rng, rounds=4)
                upd(h, r)

    # Phase 2: tie-aware multi-start polish.
    if time.process_time() < deadline:
        h, r = _tie_aware_opt(best, deadline, rng)
        upd(h, r)

    # Phase 3: Gaussian smoothing + re-optimisation.
    n_cur = len(best)
    for sigma in (0.5, 1.0, 1.5, 2.0, 3.0):
        if time.process_time() >= deadline:
            break
        hs = _smooth_gauss(best, sigma)
        if hs.sum() <= 0:
            continue
        h, r = _lbfgsb(hs, deadline, maxiter=1500, tie_tol=1e-3)
        upd(h, r)
        if r > best_r - 0.003 and time.process_time() < deadline:
            h, r = _polish(h, deadline, rng, rounds=4)
            upd(h, r)
        for dn in (1, -1):
            if time.process_time() >= deadline:
                break
            nn = n_cur + dn
            if 3 <= nn <= 500:
                hn = _resample(hs, nn)
                h, r = _polish(hn, deadline, rng, rounds=3)
                upd(h, r)

    # Phase 4: resample best to nearby sizes and polish.
    base_n = len(best)
    for dn in (1, -1, 2, -2, 3, -3, 4, 6, 8, 10, 12):
        if time.process_time() >= deadline:
            break
        new_n = base_n + dn
        if 3 <= new_n <= 500:
            hn = _resample(best, new_n)
            h, r = _polish(hn, deadline, rng, rounds=4)
            upd(h, r)

    # Phase 5: random multiplicative perturbations with polish.
    n_pert = 0
    while time.process_time() < deadline - 0.3 and n_pert < 200:
        n_pert += 1
        scale = 0.01 + 0.20 * rng.random()
        pert = best * np.exp(scale * rng.standard_normal(len(best)))
        pert = np.maximum(pert, 0.0)
        if pert.sum() <= 0:
            continue
        h, r = _lbfgsb(pert, deadline, maxiter=600)
        upd(h, r)
        if r > best_r - 0.002 and time.process_time() < deadline:
            h, r = _polish(h, deadline, rng, rounds=3)
            upd(h, r)

    # Phase 6: force zeros at ends (narrow support).
    for k in (1, 2, 3):
        if time.process_time() >= deadline:
            break
        if len(best) > 2 * k + 2:
            cand = best.copy()
            cand[:k] = 0.0
            cand[-k:] = 0.0
            h, r = _polish(cand, deadline, rng, rounds=3)
            upd(h, r)

    # Final tie-aware + polish to lock in a good tie configuration.
    if time.process_time() < deadline - 0.2:
        for tt in (3e-4, 1e-4, 3e-5):
            if time.process_time() >= deadline:
                break
            h, r = _lbfgsb(best, deadline, maxiter=2000, tie_tol=tt)
            upd(h, r)
    if time.process_time() < deadline:
        h, r = _polish(best, deadline, rng, rounds=8)
        upd(h, r)

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(12)
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    s = h.sum()
    if s <= 0.0:
        return -1.0
    L = np.convolve(h, h)
    q = (L @ L + L[:-1] @ L[1:]) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return q / (s * s * inf)


def _R_and_grad(h, tie_tol=1e-5):
    n = len(h)
    L = np.convolve(h, h)
    s = h.sum()
    if s <= 0:
        return -1.0, np.zeros(n)
    M = L.max()
    if M <= 0:
        return -1.0, np.zeros(n)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]
    b = Lf[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    r = q / (s * s * M)
    left = Lf[:-2]
    right = Lf[2:]
    dq_dL = (left + 2 * L) / 3.0 + (2 * L + right) / 3.0
    dq_dh = 2.0 * np.correlate(dq_dL, h, mode='valid')
    thr = M - tie_tol * M
    dM_dh = np.zeros(n)
    tied = np.where(L >= thr)[0]
    w = 1.0 / len(tied)
    for jmax in tied:
        lo = max(0, jmax - (n - 1))
        hi = min(n - 1, jmax)
        idx = np.arange(lo, hi + 1)
        dM_dh[idx] += w * 2.0 * h[jmax - idx]
    denom = s * s * M
    dR = dq_dh / denom - q * (2.0 / s + dM_dh / M) / denom
    return r, dR


def _lbfgsb(h0, deadline, maxiter=400, tie_tol=1e-5):
    h0 = np.maximum(np.asarray(h0, dtype=float), 0.0)
    if h0.sum() <= 0:
        return h0, -1.0
    m = h0.mean()
    x0 = h0 / m if m > 0 else h0
    best_x = x0.copy()
    best_r = _R(x0)

    def fg(x):
        if time.process_time() >= deadline:
            raise RuntimeError("stop")
        r, g = _R_and_grad(x, tie_tol=tie_tol)
        return -r, -g

    try:
        res = minimize(fg, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0),
                       options={'maxiter': maxiter, 'ftol': 1e-18,
                                'gtol': 1e-15, 'maxcor': 40})
        x = np.maximum(res.x, 0.0)
        r = _R(x)
        if r > best_r:
            best_x, best_r = x, r
    except Exception:
        pass
    return best_x, best_r


def _resample(h, new_n):
    n = len(h)
    if new_n <= 0 or new_n == n:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, new_n)
    return np.maximum(np.interp(x_new, x_old, h), 0.0)


def _smooth_opt_sym(h0, deadline, fine_mult=6):
    n = len(h0)
    fine = fine_mult * n + 1
    xc = np.linspace(-1, 1, n)
    xf = np.linspace(-1, 1, fine)
    hf = np.maximum(np.interp(xf, xc, h0), 1e-6)
    half = (fine + 1) // 2
    hf[half:] = hf[:fine - half][::-1]

    def build_half(v):
        return np.maximum(np.concatenate((v, v[:fine - half][::-1])), 0.0)

    best_v = hf[:half].copy()
    best_r = _R(build_half(best_v))

    def fg(v):
        if time.process_time() >= deadline:
            raise RuntimeError("stop")
        h = build_half(v)
        r, g = _R_and_grad(h)
        gv = g[:half].copy()
        gv[:fine - half] += g[half:][::-1]
        return -r, -gv

    try:
        res = minimize(fg, best_v, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * half,
                       options={'maxiter': 3000, 'ftol': 1e-18,
                                'gtol': 1e-15, 'maxcor': 50})
        v = np.maximum(res.x, 0.0)
        h = build_half(v)
        edges = np.linspace(0, fine, n + 1).astype(int)
        hc = np.zeros(n)
        for i in range(n):
            lo = edges[i]; hi = edges[i + 1]
            if hi <= lo:
                hi = lo + 1
            hc[i] = h[lo:hi].mean()
        hc = 0.5 * (hc + hc[::-1])
        rc = _R(hc)
        if rc > best_r:
            return hc, rc
        return _resample(h, n), best_r
    except Exception:
        return h0.copy(), _R(h0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(13579)

    if start is not None:
        best = np.maximum(np.asarray(start, dtype=float).ravel().copy(), 0.0)
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(12)
    else:
        best = np.ones(12)
    nz = np.nonzero(best)[0]
    if nz.size > 0:
        best = best[nz[0]:nz[-1] + 1].copy()
    best_r = _R(best)

    def upd(h, r):
        nonlocal best, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return
        if r > best_r + 1e-16:
            best = h.copy()
            best_r = r

    # Phase 0: tight polish with decreasing tie tolerance.
    for tt in (1e-4, 1e-5, 1e-6, 1e-7):
        if time.process_time() >= deadline:
            break
        h, r = _lbfgsb(best, deadline, maxiter=3000, tie_tol=tt)
        upd(h, r)

    # Phase 1: symmetric fine-grid optimisation across sizes.
    n0 = len(best)
    for fm in (4, 6, 8):
        if time.process_time() >= deadline:
            break
        for dn in (0, 1, -1, 2):
            if time.process_time() >= deadline:
                break
            n = n0 + dn
            if not (3 <= n <= 200):
                continue
            h, r = _smooth_opt_sym(_resample(best, n), deadline, fine_mult=fm)
            upd(h, r)

    # Phase 2: final tight polish.
    for tt in (1e-5, 1e-6, 1e-7, 1e-8):
        if time.process_time() >= deadline:
            break
        h, r = _lbfgsb(best, deadline, maxiter=5000, tie_tol=tt)
        upd(h, r)

    # Phase 3: nearby sizes.
    base_n = len(best)
    for dn in (-2, -1, 1, 2, 3):
        if time.process_time() >= deadline:
            break
        new_n = base_n + dn
        if 3 <= new_n <= 200:
            h, r = _lbfgsb(_resample(best, new_n), deadline, maxiter=3000, tie_tol=1e-6)
            upd(h, r)

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(12)
    return best

import numpy as np
import time
from scipy.optimize import minimize

def _R(h):
    s = h.sum()
    if s <= 0.0:
        return -1.0
    L = np.convolve(h, h)
    q = (L @ L + L[:-1] @ L[1:]) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return q / (s * s * inf)

def _R_and_grad(h, temp=0.0):
    n = len(h)
    L = np.convolve(h, h)
    s = h.sum()
    if s <= 0:
        return -1.0, np.zeros(n)
    Lmax = L.max()
    if Lmax <= 0:
        return -1.0, np.zeros(n)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    if temp > 0:
        e = np.exp((L - Lmax) / temp); es = e.sum()
        Ms = Lmax + temp * np.log(es); w = e / es
    else:
        Ms = Lmax
        thr = Lmax * (1.0 - 1e-6)
        tied = np.where(L >= thr)[0]
        w = np.zeros(n); w[tied] = 1.0 / len(tied)
    r = q / (s * s * Ms)
    left = Lf[:-2]; right = Lf[2:]
    dq_dL = (left + 2 * L) / 3.0 + (2 * L + right) / 3.0
    dq_dh = 2.0 * np.correlate(dq_dL, h, mode='valid')
    dM_dh = np.zeros(n)
    for jmax in np.nonzero(w)[0]:
        lo = max(0, jmax - (n - 1)); hi = min(n - 1, jmax)
        idx = np.arange(lo, hi + 1)
        dM_dh[idx] += w[jmax] * 2.0 * h[jmax - idx]
    denom = s * s * Ms
    dR = dq_dh / denom - q * (2.0 / s + dM_dh / Ms) / denom
    return r, dR

def _lbfgsb(h0, deadline, temps=(0.02, 0.005, 0.0), maxiter=3000):
    h0 = np.maximum(np.asarray(h0, dtype=float), 0.0)
    if h0.sum() <= 0:
        return h0, -1.0
    m = h0.mean()
    x = h0 / m if m > 0 else h0
    best_x = x.copy(); best_r = _R(x)
    for temp in temps:
        if time.process_time() >= deadline:
            break
        def fg(xx, _t=temp):
            if time.process_time() >= deadline:
                raise RuntimeError("stop")
            r, g = _R_and_grad(xx, temp=_t)
            return -r, -g
        try:
            res = minimize(fg, x, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(x),
                           options={'maxiter': maxiter, 'ftol': 1e-17,
                                    'gtol': 1e-14, 'maxcor': 30})
            x = np.maximum(res.x, 0.0)
            r = _R(x)
            if r > best_r:
                best_x, best_r = x.copy(), r
        except Exception:
            pass
    return best_x, best_r

def _resample(h, new_n):
    n = len(h)
    if new_n <= 0 or new_n == n:
        return h.copy()
    xo = np.linspace(0, 1, n); xn = np.linspace(0, 1, new_n)
    return np.maximum(np.interp(xn, xo, h), 0.0)

def _sym_fine(h0, deadline, mult=4, temps=(0.005, 0.001, 0.0)):
    n = len(h0)
    fine = mult * n + 1
    xc = np.linspace(-1, 1, n); xf = np.linspace(-1, 1, fine)
    hf = np.maximum(np.interp(xf, xc, h0), 1e-8)
    half = (fine + 1) // 2
    hf[half:] = hf[:fine - half][::-1]
    def build(v):
        return np.maximum(np.concatenate((v, v[:fine - half][::-1])), 0.0)
    v = hf[:half].copy()
    best_h = build(v); best_r = _R(best_h)
    for temp in temps:
        if time.process_time() >= deadline:
            break
        def fg(vv, _t=temp):
            if time.process_time() >= deadline:
                raise RuntimeError("stop")
            h = build(vv)
            r, g = _R_and_grad(h, temp=_t)
            gv = g[:half].copy(); gv[:fine - half] += g[half:][::-1]
            return -r, -gv
        try:
            res = minimize(fg, v, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * half,
                           options={'maxiter': 3000, 'ftol': 1e-17,
                                    'gtol': 1e-14, 'maxcor': 40})
            v = np.maximum(res.x, 0.0)
            h = build(v); r = _R(h)
            if r > best_r:
                best_r = r; best_h = h
        except Exception:
            pass
    edges = np.linspace(0, fine, n + 1).astype(int)
    hc = np.zeros(n)
    for i in range(n):
        lo = edges[i]; hi = max(edges[i + 1], lo + 1)
        hc[i] = best_h[lo:hi].mean()
    hc = 0.5 * (hc + hc[::-1])
    if _R(hc) >= best_r:
        return hc, _R(hc)
    return _resample(best_h, n), best_r

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(777777)

    if start is not None:
        best = np.maximum(np.asarray(start, dtype=float).ravel().copy(), 0.0)
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(11)
    else:
        best = np.ones(11)
    nz = np.nonzero(best)[0]
    if nz.size > 0:
        best = best[nz[0]:nz[-1] + 1].copy()
    best_r = _R(best)

    def upd(h, r):
        nonlocal best, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() > 0 and r > best_r + 1e-15:
            best = h.copy(); best_r = r

    # Phase 1: symmetric fine-grid lifting (key improvement).
    for fm in (2, 3, 4, 6, 8):
        if time.process_time() >= deadline:
            break
        h, r = _sym_fine(best, deadline, mult=fm,
                         temps=(0.01, 0.003, 0.001, 0.0))
        upd(h, r)

    # Phase 2: annealed refine at current N.
    if time.process_time() < deadline:
        h, r = _lbfgsb(best, deadline,
                       temps=(0.005, 0.002, 0.0005, 0.0), maxiter=4000)
        upd(h, r)

    # Phase 3: sweep nearby N.
    base = best.copy()
    for dn in (-4, -3, -2, -1, 1, 2, 3, 4, 6, 8, -6, -8, 10, 12, -10, -12):
        if time.process_time() >= deadline:
            break
        nn = len(base) + dn
        if 3 <= nn <= 2000:
            hn = _resample(base, nn)
            h, r = _lbfgsb(hn, deadline,
                           temps=(0.005, 0.001, 0.0), maxiter=2500)
            upd(h, r)
            if r > best_r - 0.003:
                h, r = _sym_fine(h, deadline, mult=3,
                                 temps=(0.002, 0.0005, 0.0))
                upd(h, r)

    # Phase 4: perturb-and-polish loop.
    nt = 0
    while time.process_time() < deadline - 0.5 and nt < 200:
        nt += 1
        scale = 0.01 + 0.15 * rng.random()
        pert = best * np.exp(scale * rng.standard_normal(len(best)))
        pert = np.maximum(pert, 0.0)
        if pert.sum() <= 0:
            continue
        h, r = _lbfgsb(pert, deadline, temps=(0.002, 0.0), maxiter=1500)
        if r > best_r:
            upd(h, r)
            h, r = _sym_fine(h, deadline, mult=3,
                             temps=(0.001, 0.0))
            upd(h, r)

    # Final polish.
    if time.process_time() < deadline - 0.3:
        h, r = _lbfgsb(best, deadline, temps=(0.0005, 0.0), maxiter=8000)
        upd(h, r)

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(11)
    return best
